// Per-surface JNI state of `dev.nve.host.NativeRuntime` over `libnve_runtime` (ABI v6).
#pragma once

#include <jni.h>

#include <nve/generated/nve_abi.generated.h>
#include <nve/generated/nve_jni_frame.generated.hpp>
#include <nve/host/owned_events.hpp>
#include <nve/host/runtime_session.hpp>
#include <nve/host/value_tree.hpp>

// Generated by CMake from the Java sources (`dev.nve.host.generated.NveRuntimeAbi` /
// `NveJniFrame`): `static_assert`s every `STATUS_*`, `MEASURE_FLAG_*`, the runtime schema hash,
// and the packed frame layout hash against this build's C / C++ halves, so a stale Java half
// fails the build.
#include "nve_java_contract.generated.hpp"

#include <array>
#include <cstddef>
#include <cstdint>
#include <optional>
#include <atomic>
#include <span>
#include <string>
#include <thread>
