namespace nve::android {

/// `GlobalRef` `DirectByteBuffer` over native memory, recreated only when `(ptr, len)` changes.
class CachedDirectBuffer {
 public:
  /// Sets `*out` to the global ref for `[ptr, ptr + len)` (`nullptr` for an empty range). `false`
  /// on a JNI failure, with the pending exception cleared and `*out == nullptr`.
  [[nodiscard]] bool sync(JNIEnv* env, const void* ptr, size_t len, jobject* out);
  void release(JNIEnv* env) noexcept;

 private:
  const void* ptr_ = nullptr;
  size_t len_ = 0u;
  jobject ref_ = nullptr;
};

/// A Java callback target held as a `GlobalRef` with its resolved method.
struct JavaCallback {
  jobject target = nullptr;
  jmethodID method = nullptr;
  void release(JNIEnv* env) noexcept;
};

/// A Java `NativeRuntime.HostCallbackBridge` held as a `GlobalRef` with resolved methods.
struct JavaHostBridge {
  jobject target = nullptr;
  jmethodID invoke_method = nullptr;
  jmethodID publish_method = nullptr;
  jclass byte_array_cls = nullptr;
  void release(JNIEnv* env) noexcept;
};

struct AndroidSurface {
  nve::host::RuntimeSession session;
  std::optional<nve::host::RuntimeSceneGuard> scene;
  JavaVM* jvm = nullptr;
  /// The thread that created the surface: the runtime's owner thread. Every entry point except
  /// `pairIsConnected`, `completeHostRequest`, `pushHostEvent`, and `publishHostChannel` is
  /// refused elsewhere (`owned_surface`).
  std::thread::id owner_thread = std::this_thread::get_id();
  /// Set by a call refused off the owner thread (a static message: writing `last_error` there
  /// would race the owner); the owner's next `lastError` reports and clears it.
  std::atomic<const char*> refused{nullptr};
  uint32_t surface_id = 1u;
  std::array<CachedDirectBuffer, nve::jni_frame::SLABS_LEN> slabs{};
  /// Tables packed by the previous `acquireScene`: only `[table_count, prev_table_count)` slab
  /// slots need clearing on the next one.
  uint32_t prev_table_count = 0u;
  /// 64-byte-aligned reusable `NveEvent` scratch slab for `NVEV` v2 dispatch (borrows the Java
  /// direct buffer's byte arena with zero steady-state allocations).
  std::vector<NveEvent, nve::host::AlignedAllocator<NveEvent, NVE_EVENT_ALIGN>> events;
  /// Reusable scratch storage for decoding `setProps` binary `NveBinValue` maps with zero steady-state allocs.
  nve::host::NveValueTree props_tree;
  JavaCallback measurer;
  jfloatArray measure_out = nullptr;
  JavaCallback wake;
  JavaCallback intrinsic_size_invalidated;
  JavaHostBridge host_bridge;
  std::string last_error;
};

[[nodiscard]] inline AndroidSurface* surface_of(jlong handle) noexcept {
  return reinterpret_cast<AndroidSurface*>(handle);
}

/// The surface behind `handle` on its owner thread, else `nullptr` (the caller returns
/// `INVALID_ARG` touching nothing): the scene guard, slab cache, event scratch, and `last_error`
/// are owner-thread state, and the runtime itself is single-threaded.
[[nodiscard]] inline AndroidSurface* owned_surface(jlong handle) noexcept {
  AndroidSurface* s = surface_of(handle);
  if (s == nullptr || std::this_thread::get_id() == s->owner_thread) return s;
  s->refused.store("called off the surface's owner thread (the thread that created it)", std::memory_order_relaxed);
  return nullptr;
}

/// Validates a direct `ByteBuffer` holding `len` bytes (`(nullptr, 0)` or a 0-capacity direct
/// buffer with `len == 0` is allowed as an empty slice).
[[nodiscard]] inline bool direct_buffer_span(JNIEnv* env, jobject buf, jint len,
                                             std::span<const uint8_t>* out) noexcept {
  if (len < 0 || out == nullptr) return false;
  if (buf == nullptr) {
    if (len != 0) return false;
    *out = {};
    return true;
  }
  const jlong cap = env->GetDirectBufferCapacity(buf);
  if (cap < 0 || static_cast<jlong>(len) > cap) return false;
  if (len == 0) {
    *out = {};
    return true;
  }
  const auto* data = static_cast<const uint8_t*>(env->GetDirectBufferAddress(buf));
  if (data == nullptr) return false;
  *out = std::span<const uint8_t>(data, static_cast<size_t>(len));
  return true;
}

/// Releases the held scene (every mutating call does this first so the runtime is never `Busy`).
void release_scene(AndroidSurface& s) noexcept;

/// Drops every cached slab `DirectByteBuffer` (app swap, pairing change, destroy).
void release_buffers(AndroidSurface& s, JNIEnv* env) noexcept;

/// Records `status` (with the runtime's message) as the surface's last error and returns it
/// (`NVE_RUNTIME_OK` clears the last error). Every JNI entry point returns a status, never a value.
jint status_of(AndroidSurface& s, NveRuntimeStatus status);

/// Writes `value` to `out[0]` when `out` is a non-empty array.
void write_out(JNIEnv* env, jintArray out, jint value);

/// UTF-8 copy of a Java string (`""` for null or on a JNI failure; lone surrogates become U+FFFD).
std::string utf8_of(JNIEnv* env, jstring str);

/// Java string of UTF-8 bytes (malformed sequences become U+FFFD; never modified UTF-8).
jstring java_string(JNIEnv* env, const uint8_t* utf8, size_t len);

/// `true` (and the exception cleared) when a JNI call left an exception pending.
inline bool clear_exception(JNIEnv* env) noexcept {
  if (!env->ExceptionCheck()) return false;
  env->ExceptionClear();
  return true;
}

}  // namespace nve::android
